const incoming = $input.first().json;
const payload = incoming.body ?? incoming;
const rows = Array.isArray(payload.transactions) ? payload.transactions : [];

const escapeCsv = (value) => {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return `\"${text.replace(/\"/g, '\"\"')}\"`;
};

const headers = [
  'Transaction ID', 'Date', 'Customer', 'Phone', 'Service', 'Kg', 'Loads',
  'Base Amount', 'Add-ons', 'Add-on Details', 'Total', 'Cash Received',
  'GCash Received', 'GCash Reference', 'Payment Method', 'Pickup Date', 'Notes'
];

const lines = [headers.map(escapeCsv).join(',')];
for (const row of rows) {
  const service = row.services?.code ?? row.services?.label ?? '';
  const values = [
    row.transaction_code ?? row.transaction_no ?? '',
    row.transaction_date ?? '',
    row.customer_name ?? '',
    row.phone_number ?? '',
    service,
    row.kg ?? '',
    row.no_of_loads ?? '',
    row.base_amount ?? 0,
    row.add_ons ?? 0,
    row.add_on_items ?? [],
    row.total_amount ?? 0,
    row.cash_amount ?? 0,
    row.gcash_amount ?? 0,
    row.gcash_reference ?? '',
    row.payment_method ?? '',
    row.pickup_date ?? '',
    row.notes ?? ''
  ];
  lines.push(values.map(escapeCsv).join(','));
}

const filename = `${payload.export_name || 'aquaspin-transactions'}.csv`;
return [{ json: { filename, csv: lines.join('\n'), row_count: rows.length } }];
